#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdlib>

int main() {
    int n, coins;
    std::cin >> n >> coins;
    std::vector<std::string> vals_str(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> vals_str[i];
    }
    std::vector<int> vals(n);
    for (int i = 0; i < n; ++i) {
        vals[i] = std::stoi(vals_str[i]);
    }

    int oddCount = 0, evenCount = 0, cuts = 0;
    std::vector<int> diffs;

    for (int i = 0; i < n - 1; ++i) {
        int val = vals[i];
        if (val % 2 == 0) {
            ++evenCount;
        } else {
            ++oddCount;
        }
        if (oddCount == evenCount) {
            int nextVal = vals[i + 1];
            int difference = std::abs(nextVal - val);
            diffs.push_back(difference);
        }
    }

    std::sort(diffs.begin(), diffs.end());

    for (int d : diffs) {
        if (d <= coins) {
            coins -= d;
            ++cuts;
        } else {
            break;
        }
    }

    std::cout << cuts << std::endl;
    return 0;
}
